INSERT IGNORE INTO rule_field_validation
  (project_id,`scope`,validation_code,validation_name,validation_type,validation_value,error_message,description,status,create_time,update_time)
VALUES
  (0,'GLOBAL','builtin_required','必填','REQUIRED',NULL,'该字段不能为空','校验字段必须提供有效值。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_digits','数字','REGEX','^[0-9]*$','请输入数字','只允许输入数字。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_digits_min_16','至少16位数字','REGEX','^\\d{16,}$','请输入至少16位数字','只允许输入不少于16位的数字。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_digits_15_to_18','15-18位数字','REGEX','^\\d{15,18}$','请输入15至18位数字','只允许输入不少于15位且不超过18位的数字。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_chinese','汉字','REGEX','^[\\u4e00-\\u9fa5]{0,}$','请输入汉字','只允许输入汉字。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_alphanumeric','英文和数字','REGEX','^[a-zA-Z0-9]+$','请输入英文或数字','只允许输入英文字母和数字。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_email','邮箱','REGEX','^\\w+([-+.]\\w+)*@\\w+([-.]\\w+)*\\.\\w+([-.]\\w+)*$','请输入正确的邮箱地址','校验常用邮箱地址格式。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_domain','域名','REGEX','^[a-zA-Z0-9][-a-zA-Z0-9]{0,62}(\\.[a-zA-Z0-9][-a-zA-Z0-9]{0,62})+\\.?$','请输入正确的域名','校验常用域名格式。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_mobile','手机号','REGEX','^1[0-9]{10}$','请输入正确的手机号','校验中国大陆11位手机号格式。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_id_card','身份证号','REGEX','^[1-9]\\d{5}(18|19|20)\\d{2}((0[1-9])|(1[0-2]))(([0-2][1-9])|10|20|30|31)\\d{3}[0-9Xx]$','请输入正确的身份证号','校验中国大陆18位身份证号的基础格式。',1,NOW(),NOW()),
  (0,'GLOBAL','builtin_ip_address','IP地址','REGEX','^((?:(?:25[0-5]|2[0-4]\\d|[01]?\\d?\\d)\\.){3}(?:25[0-5]|2[0-4]\\d|[01]?\\d?\\d))$','请输入正确的IP地址','校验 IPv4 地址格式。',1,NOW(),NOW());
